import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"Next.js reference boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/frontend/next/index.md","filePath":"workbench/frontend/next/index.md"}'),o={name:"workbench/frontend/next/index.md"};function i(s,e,c,d,l,p){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="next-js-reference-boundaries" tabindex="-1">Next.js reference boundaries <a class="header-anchor" href="#next-js-reference-boundaries" aria-label="Permalink to “Next.js reference boundaries”">​</a></h1><p>Baseline: <strong>Next.js 16.4.3 App Router, React 19.3.0, TypeScript 5.9.3, Node 24.18.0</strong>. Official APIs checked 2026-10-27; this is a declared teaching baseline, not an upgrade policy for every application.</p><h2 id="public-read-only-application" tabindex="-1"><span class="hub-section-number">1 </span>Public read-only application <a class="header-anchor" href="#public-read-only-application" aria-label="Permalink to “1 Public read-only application”">​</a></h2><p>Copy <code>read-only/</code> into an isolated directory; install its pinned package.json, then run <code>npm run build</code>, <code>npm run typecheck</code> and <code>npm start</code>. Browse <code>/courses</code> and a detail link on loopback port 4175. It has two fixed public courses and no external API, auth or persistent data. No root homepage is supplied; <code>/courses</code> is the entry route.</p><p>The deliberate config sets cacheComponents:false. Current generator defaults may choose another model; use the checked config rather than silently combining recipes. The <a href="./../../../senior_growth/React/next-app-router.html">route lesson</a> includes the canonical source files.</p><h2 id="security-integration-fragments" tabindex="-1"><span class="hub-section-number">2 </span>Security integration fragments <a class="header-anchor" href="#security-integration-fragments" aria-label="Permalink to “2 Security integration fragments”">​</a></h2><p><code>security-fragments/</code> contains the separate SQL/DAL/session/body/parser/Route Handler/Server Action worked boundary from <a href="./../../../senior_growth/React/next-server-security.html">the server security lesson</a>. It is <strong>not a standalone login application</strong>: it needs the authentication integration&#39;s app_user table, PostgreSQL, sessions, trusted origin configuration and a UI. Do not copy it into the public app and claim an authenticated deployment without that integration.</p><p>The schema is not automatically applied. No credentials or services are provisioned. Metadata/images/fonts and ISR instrumentation remain explicit extensions of the public fixture; their required binary assets/upstream are not invented here.</p><p><a href="./../../../practice/frontend/f06-next.html">Practice F06</a> specifies integration evidence. <a href="./../../../frontend/verification.html">Author verification</a> records executed subsets separately.</p><p>The pure <code>security-fragments/check.ts</code> runner covers body/parser failure and cleanup cases with local Request/ReadableStream fixtures. Bundle it with the React reference esbuild tool (Node platform, ESM output), then run the emitted file; no session, provider or database is contacted.</p>',10)])])}const f=t(o,[["render",i]]);export{h as __pageData,f as default};
